Definition smear_step (s : Z) (x : Z) : Z := Z.lor x (Z.shiftr x s).
(* [comment removed for export] *)
Definition smear6 (x : Z) : Z :=
  smear_step 32 (smear_step 16 (smear_step 8 (smear_step 4 (smear_step 2 (smear_step 1 x))))).

