Definition ones_from (lo : Z) (v : Z) : Prop :=
  0 <= v /\ (forall n, 47 <= n -> Z.testbit v n = false) /\ (forall n, 0 <= n -> lo <= n <= 46 -> Z.testbit v n = true).

